package nativespeech

import (
	"encoding/base64"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"testing"
)

func TestCompatibleMP3SampleRateDoesNotRelaxEleven(t *testing.T) {
	raw, e := base64.StdEncoding.DecodeString("")
	require.NoError(t, e)
	require.NoError(t, ValidateAudioFile(raw, "audio/mpeg", 10))
	assert.Error(t, validateAudio(raw, "audio/mpeg", 10))
	assert.Error(t, ValidateAudioFile(raw[:100], "audio/mpeg", 10))
}
